    );

    expect(result).toMatchObject({
      _email_verify_token: 'verify',
      _perishable_token: 'perishable',
      _perishable_token_expires_at: 'raw-expiry',
      _password_changed_at: 'raw-changed',
      _tombstone: true,
      _email_verify_token_expires_at: 'raw-email-expiry',
      _account_lockout_expires_at: 'raw-lockout-expiry',
      _password_history: [{ password: 'old' }],
      expiresAt: { __type: 'Date', iso: '2024-04-05T06:07:08.000Z' },
    });
    expect(result._acl).toBeUndefined();
  });

  test('synthesizes and filters authData for _User rows', () => {
    expect(
      mongoObjectToParseObject(
        '_User',
        {
          _auth_data_facebook: { id: 'fb-1' },
