  });

  test('rejects a mixture of regex and non-regex values in $all', () => {
    expectParseError(
      () => transformConstraint({ $all: [{ $regex: '^\\Qfoo\\E' }, 'plain'] }, { type: 'Array' }, 'tags'),
      Parse.Error.INVALID_JSON,
      /All \$all values must be of regex type or none/
    );
  });

  test('rejects a non-array $all value', () => {
