    expect(result.data.buffer.toString('base64')).toBe('aGVsbG8=');
    expect(result.location).toEqual([10, 20]);
    expect(result.shape).toEqual({
      type: 'Polygon',
      coordinates: [[[20, 10], [40, 30], [60, 50], [20, 10]]],
    });
    expect(result.attachment).toBe('hello.txt');
  });

  test('adds the legacy ACL representation without mutating the input', () => {
    const rest = { _wperm: ['role:admin', 'user-1'], _rperm: ['user-1', '*'] };
    expect(parseObjectToMongoObjectForCreate('Game', rest, schema)).toEqual({
      _wperm: ['role:admin', 'user-1'],
      _rperm: ['user-1', '*'],
      _acl: {
        'role:admin': { w: true },
        'user-1': { w: true, r: true },
        '*': { r: true },
      },
    });
    expect(rest).toEqual({ _wperm: ['role:admin', 'user-1'], _rperm: ['user-1', '*'] });
  });

  test('skips relations and undefined values', () => {
    expect(
      parseObjectToMongoObjectForCreate(
        'Game',
        {
          friend: { __type: 'Relation', className: '_User' },
          name: undefined,
          score: 0,
        },
        schema
      )
    ).toEqual({ score: 0 });
  });

  test('rejects nested keys containing $ or .', () => {
    expectParseError(
      () =>
        parseObjectToMongoObjectForCreate(
          'Game',
          { profile: { 'bad.key': 1 } },
          schema
        ),
      Parse.Error.INVALID_NESTED_KEY,
      "Nested keys should not contain the '$' or '.' characters"
    );

    expectParseError(
      () =>
        parseObjectToMongoObjectForCreate(
          'Game',
          { profile: { '$bad': 1 } },
          schema
        ),
      Parse.Error.INVALID_NESTED_KEY,
      "Nested keys should not contain the '$' or '.' characters"
    );
  });

  test('rejects an untransformed ACL field', () => {
    expect(() =>
      parseObjectToMongoObjectForCreate('Game', { ACL: { 'user-1': { read: true } } }, schema)
    ).toThrow('There was a problem transforming an ACL.');
  });

  test('rejects authData subfields that should have been converted already', () => {
    expectParseError(
      () =>
        parseObjectToMongoObjectForCreate(
          '_User',
          { 'authData.facebook.id': 'fb-1' },
          schema
        ),
      Parse.Error.INVALID_KEY_NAME,
      'can only query on authData.facebook.id'
    );
  });

  test('trusts already transformed authData keys', () => {
    expect(
      parseObjectToMongoObjectForCreate(
        '_User',
        { _auth_data_facebook: { id: 'fb-1' } },
        schema
      )
    ).toEqual({ _auth_data_facebook: { id: 'fb-1' } });
  });

  test('does not prefix Bytes fields as pointers even when the schema says Pointer', () => {
    const pointerSchema = schemaWith({ data: { type: 'Pointer', targetClass: '_User' } });
    const result = parseObjectToMongoObjectForCreate(
      'Game',
      { data: { __type: 'Bytes', base64: 'aGVsbG8=' } },
      pointerSchema
    );
    expect(result.data).toBeInstanceOf(mongodb.Binary);
    expect(result._p_data).toBeUndefined();
  });
});

describe('transformUpdate', () => {
  const schema = schemaWith({
    owner: { type: 'Pointer', targetClass: '_User' },
    score: { type: 'Number' },
    profile: { type: 'Object' },
    tags: { type: 'Array' },
    friend: { type: 'Relation', targetClass: '_User' },
  });

  test('builds a $set update for ordinary values and built-in fields', () => {
    expect(
      transformUpdate(
        'Game',
        {
          name: 'New name',
          objectId: 'game-1',
          sessionToken: 'sess',
          _failed_login_count: 4,
        },
        schema
      )
    ).toEqual({
      $set: {
        name: 'New name',
        _id: 'game-1',
        _session_token: 'sess',
        _failed_login_count: 4,
      },
    });
  });

  test('adds both modern and legacy ACL fields', () => {
    expect(
      transformUpdate('Game', { _wperm: ['role:admin', 'user-1'], _rperm: ['user-1', '*'] }, schema)
    ).toEqual({
      $set: {
        _wperm: ['role:admin', 'user-1'],
        _rperm: ['user-1', '*'],
        _acl: {
          'role:admin': { w: true },
          'user-1': { w: true, r: true },
          '*': { r: true },
        },
      },
    });
  });

  test('prefixes pointers and leaves pointers inside nested documents unprefixed', () => {
    const result = transformUpdate(
      'Game',
      {
        owner: { __type: 'Pointer', className: '_User', objectId: 'u-1', extra: 'discarded' },
        profile: {
          friend: { __type: 'Pointer', className: '_User', objectId: 'u-2', extra: 'discarded' },
        },
      },
      schema
    );

    expect(result.$set._p_owner).toBe('_User$u-1');
    expect(result.$set.profile).toEqual({
      friend: { __type: 'Pointer', className: '_User', objectId: 'u-2' },
    });
  });

  test('coerces date-bearing update fields from strings', () => {
    const date = '2024-07-08T09:10:11.000Z';
    expect(
      transformUpdate(
        '_User',
        {
          createdAt: date,
          updatedAt: date,
          expiresAt: date,
          _email_verify_token_expires_at: date,
          _account_lockout_expires_at: date,
          _perishable_token_expires_at: date,
          _password_changed_at: date,
          lastUsed: date,
        },
        schema
      )
    ).toEqual({
      $set: {
        _created_at: new Date(date),
        _updated_at: new Date(date),
        expiresAt: new Date(date),
        _email_verify_token_expires_at: new Date(date),
        _account_lockout_expires_at: new Date(date),
        _perishable_token_expires_at: new Date(date),
        _password_changed_at: new Date(date),
        _last_used: new Date(date),
      },
    });
  });

  test('maps timesUsed and coerces GlobalConfig objectIds', () => {
    expect(transformUpdate('Game', { timesUsed: 5 }, schema)).toEqual({
      $set: { times_used: 5 },
    });
    expect(transformUpdate('_GlobalConfig', { objectId: '12' }, schemaWith({}))).toEqual({
      $set: { _id: 12 },
    });
  });

  test('lifts update operators to the top level', () => {
    const iso = '2024-08-09T10:11:12.000Z';
    expect(
      transformUpdate(
        'Game',
        {
          score: { __op: 'Increment', amount: 2 },
          tags: { __op: 'Add', objects: ['a', { __type: 'Date', iso }] },
          uniqueTags: { __op: 'AddUnique', objects: ['b'] },
          removedTags: { __op: 'Remove', objects: ['c'] },
          obsolete: { __op: 'Delete' },
          createdOnInsert: { __op: 'SetOnInsert', amount: 'first' },
        },
        schema
      )
    ).toEqual({
      $inc: { score: 2 },
      $push: { tags: { $each: ['a', new Date(iso)] } },
      $addToSet: { uniqueTags: { $each: ['b'] } },
      $pullAll: { removedTags: ['c'] },
      $unset: { obsolete: '' },
      $setOnInsert: { createdOnInsert: 'first' },
    });
  });

  test('flattens update operators inside nested documents', () => {
    const result = transformUpdate(
      'Game',
      {
        profile: {
          views: { __op: 'Increment', amount: 1 },
          tags: { __op: 'Add', objects: ['x'] },
          gone: { __op: 'Delete' },
          removed: { __op: 'Remove', objects: ['y'] },
        },
      },
      schema
    );

    expect(result.$set.profile.views).toBe(1);
    expect(result.$set.profile.tags).toEqual(['x']);
    expect(result.$set.profile.removed).toEqual([]);
    expect(result.$set.profile).toHaveProperty('gone');
    expect(result.$set.profile.gone).toBeUndefined();
  });

  test('skips relation values and preserves dotted field names', () => {
    expect(
      transformUpdate(
        'Game',
        {
          friend: { __type: 'Relation', className: '_User' },
          'profile.name': 'Ace',
        },
        schema
      )
    ).toEqual({
      $set: { 'profile.name': 'Ace' },
    });
  });

  test('rejects invalid nested keys in an update', () => {
    expectParseError(
      () => transformUpdate('Game', { profile: { 'bad.key': 1 } }, schema),
      Parse.Error.INVALID_NESTED_KEY,
      "Nested keys should not contain the '$' or '.' characters"
    );
  });

  test('validates update operator arguments', () => {
    expectParseError(
      () => transformUpdate('Game', { score: { __op: 'Increment', amount: '2' } }, schema),
      Parse.Error.INVALID_JSON,
      'incrementing must provide a number'
    );
    expectParseError(
      () => transformUpdate('Game', { tags: { __op: 'Add', objects: 'x' } }, schema),
      Parse.Error.INVALID_JSON,
      'objects to add must be an array'
    );
    expectParseError(
      () => transformUpdate('Game', { tags: { __op: 'Remove', objects: 'x' } }, schema),
      Parse.Error.INVALID_JSON,
      'objects to remove must be an array'
    );
  });

  test('rejects unsupported update operators', () => {
    expectParseError(
      () => transformUpdate('Game', { score: { __op: 'Multiply', amount: 2 } }, schema),
      Parse.Error.COMMAND_UNAVAILABLE,
      'The Multiply operator is not supported yet.'
    );
  });

  test('rejects function atoms', () => {
    expectParseError(
      () => transformUpdate('Game', { callback: function noop() {} }, schema),
      Parse.Error.INVALID_JSON,
      /cannot transform value/
    );
  });
});

describe('mongoObjectToParseObject', () => {
  const schema = schemaWith({
    name: { type: 'String' },
    age: { type: 'Number' },
    owner: { type: 'Pointer', targetClass: '_User' },
    notAPointer: { type: 'String' },
    avatar: { type: 'File' },
    location: { type: 'GeoPoint' },
    area: { type: 'Polygon' },
    data: { type: 'Bytes' },
    tags: { type: 'Array' },
    friend: { type: 'Relation', targetClass: '_User' },
  });

  test('passes primitive values through unchanged', () => {
    expect(mongoObjectToParseObject('Game', 'text', schema)).toBe('text');
    expect(mongoObjectToParseObject('Game', 42, schema)).toBe(42);
    expect(mongoObjectToParseObject('Game', true, schema)).toBe(true);
    expect(mongoObjectToParseObject('Game', null, schema)).toBeNull();
    expect(mongoObjectToParseObject('Game', undefined, schema)).toBeUndefined();
  });

  test('maps Mongo scalar wrappers and binary data', () => {
    expect(mongoObjectToParseObject('Game', mongodb.Long.fromNumber(42), schema)).toBe(42);
    expect(mongoObjectToParseObject('Game', new mongodb.Double(1.5), schema)).toBe(1.5);
    expect(
      mongoObjectToParseObject('Game', new mongodb.Binary(Buffer.from('hello')), schema)
    ).toEqual({ __type: 'Bytes', base64: 'aGVsbG8=' });
  });

  test('maps the standard Mongo row fields to Parse representation', () => {
    const created = new Date('2024-01-02T03:04:05.678Z');
    const updated = new Date('2024-02-03T04:05:06.789Z');
    const lastUsed = new Date('2024-03-04T05:06:07.890Z');

    expect(
      mongoObjectToParseObject(
        '_User',
        {
          _id: 'user-1',
          name: 'Alice',
          age: 30,
          _hashed_password: 'hash',
          _session_token: 'token',
          _created_at: created,
          _updated_at: updated,
          lastUsed,
          timesUsed: 7,
          _failed_login_count: 2,
          _timestamps: { ignored: true },
        },
        schema
      )
    ).toEqual({
      objectId: 'user-1',
      name: 'Alice',
      age: 30,
      _hashed_password: 'hash',
      sessionToken: 'token',
      createdAt: created.toISOString(),
      updatedAt: updated.toISOString(),
      lastUsed: lastUsed.toISOString(),
      timesUsed: 7,
      _failed_login_count: 2,
    });
  });

  test('maps expiration and token fields and drops the stored ACL', () => {
    const result = mongoObjectToParseObject(
      '_User',
      {
        _email_verify_token: 'verify',
        _perishable_token: 'perishable',
        _perishable_token_expires_at: 'raw-expiry',
        _password_changed_at: 'raw-changed',
        _tombstone: true,
        _email_verify_token_expires_at: 'raw-email-expiry',
        _account_lockout_expires_at: 'raw-lockout-expiry',
        _password_history: [{ password: 'old' }],
        expiresAt: new Date('2024-04-05T06:07:08.000Z'),
        _acl: { 'user-1': { r: true } },
      },
      schema
    );

    expect(result).toMatchObject({
      _email_verify_token: 'verify',
      _perishable_token: 'perishable',
      _perishable_token_expires_at: 'raw-expiry',
      _password_changed_at: 'raw-changed',
      _tombstone: true,
      _email_verify_token_expires_at: 'raw-email-expiry',
      _account_lockout_expires_at: 'raw-lockout-expiry',
      _password_history: [{ password: 'old' }],
      expiresAt: { __type: 'Date', iso: '2024-04-05T06:07:08.000Z' },
    });
    expect(result._acl).toBeUndefined();
  });

  test('synthesizes and filters authData for _User rows', () => {
    expect(
      mongoObjectToParseObject(
        '_User',
        {
          _auth_data_facebook: { id: 'fb-1' },
          _auth_data_google: { id: 'g-1' },
          authData: { should: 'be ignored' },
        },
        schema
      )
    ).toEqual({
      authData: {
        facebook: { id: 'fb-1' },
        google: { id: 'g-1' },
      },
    });
  });

  test('keeps authData for non-user classes', () => {
    expect(
      mongoObjectToParseObject(
        'Game',
        {
          authData: { custom: true },
          _auth_data_facebook: { id: 'should-drop' },
        },
        schema
      )
    ).toEqual({ authData: { custom: true } });
  });

  test('resolves pointers and drops missing, non-pointer, and null pointer columns', () => {
    expect(
      mongoObjectToParseObject(
        'Game',
        {
          _p_owner: '_User$u-1',
          _p_missing: '_User$u-2',
          _p_notAPointer: '_User$u-3',
          _p_nullPointer: null,
        },
        {
          fields: {
            owner: { type: 'Pointer', targetClass: '_User' },
            notAPointer: { type: 'String' },
            nullPointer: { type: 'Pointer', targetClass: '_User' },
          },
        }
      )
    ).toEqual({
      owner: { __type: 'Pointer', className: '_User', objectId: 'u-1' },
    });
  });

  test('rejects pointer strings with the wrong target class', () => {
    expect(() =>
      mongoObjectToParseObject('Game', { _p_owner: 'Game$g-1' }, schema)
    ).toThrow('pointer to incorrect className');
  });

  test('converts File, GeoPoint, Polygon, and Bytes database values', () => {
    const result = mongoObjectToParseObject(
      'Game',
      {
        avatar: 'avatar.png',
        location: [10, 20],
        area: {
          type: 'Polygon',
          coordinates: [
            [
              [10, 20],
              [30, 40],
              [50, 60],
              [10, 20],
            ],
          ],
        },
        data: new mongodb.Binary(Buffer.from('hello')),
        tags: ['one', 'two'],
      },
      schema
    );

    expect(result).toEqual({
      avatar: { __type: 'File', name: 'avatar.png' },
      location: { __type: 'GeoPoint', latitude: 20, longitude: 10 },
      area: {
        __type: 'Polygon',
        coordinates: [
          [20, 10],
          [40, 30],
          [60, 50],
          [20, 10],
        ],
      },
      data: { __type: 'Bytes', base64: 'aGVsbG8=' },
      tags: ['one', 'two'],
    });
  });

  test('converts nested dates and Mongo values recursively', () => {
    const date = new Date('2024-06-07T08:09:10.000Z');
    expect(
      mongoObjectToParseObject(
        'Game',
        {
          profile: {
            joined: date,
            count: mongodb.Long.fromNumber(3),
            values: [date, { count: mongodb.Long.fromNumber(4) }],
          },
        },
        schema
      )
    ).toEqual({
      profile: {
        joined: { __type: 'Date', iso: date.toISOString() },
        count: 3,
        values: [{ __type: 'Date', iso: date.toISOString() }, { count: 4 }],
      },
    });
  });

  test('synthesizes relation fields declared in schema', () => {
    expect(mongoObjectToParseObject('Game', { name: 'Chess' }, schema)).toEqual({
      name: 'Chess',
      friend: { __type: 'Relation', className: '_User' },
    });
  });

  test('drops unrecognized reserved keys', () => {
    expect(
      mongoObjectToParseObject('Game', { name: 'Chess', _mystery: 'do not expose' }, schema)
    ).toEqual({
      name: 'Chess',
      friend: { __type: 'Relation', className: '_User' },
    });
  });

  test('does not mutate the input when legacy permissions are present', () => {
    const mongoObject = { _rperm: ['user-1'], _wperm: ['role:admin'], name: 'Chess' };
    const result = mongoObjectToParseObject('Game', mongoObject, schema);

    expect(result._rperm).toEqual(['user-1']);
    expect(result._wperm).toEqual(['role:admin']);
    expect(mongoObject).not.toHaveProperty('_rperm');
    expect(mongoObject).not.toHaveProperty('_wperm');
  });

  test('rejects functions and symbols', () => {
    expect(() => mongoObjectToParseObject('Game', function noop() {}, schema)).toThrow(
      'bad value in mongoObjectToParseObject'
    );
    expect(() => mongoObjectToParseObject('Game', Symbol('bad'), schema)).toThrow(
      'bad value in mongoObjectToParseObject'
    );
  });
});
